  <div class="dock-center"><div class="dock-transport"><button class="dock-icon-button" id="dockPrevious" type="button" aria-label="Предыдущая сказка" disabled><svg class="icon"><use href="{{ asset('assets/icons.svg') }}#track-previous"></use></svg></button><button class="dock-icon-button" id="dockBack" type="button" aria-label="Назад на 10 секунд" disabled><svg class="icon"><use href="{{ asset('assets/icons.svg') }}#skip-back"></use></svg></button><button class="dock-play" id="dockPlay" type="button" aria-label="Воспроизвести" disabled><svg class="icon"><use href="{{ asset('assets/icons.svg') }}#play"></use></svg></button><button class="dock-icon-button" id="dockForward" type="button" aria-label="Вперёд на 10 секунд" disabled><svg class="icon"><use href="{{ asset('assets/icons.svg') }}#skip-forward"></use></svg></button><button class="dock-icon-button" id="dockNext" type="button" aria-label="Следующая сказка" disabled><svg class="icon"><use href="{{ asset('assets/icons.svg') }}#track-next"></use></svg></button></div>
