  <div class="dock-actions"><button class="dock-icon-button" id="dockRepeat" type="button" aria-label="Повторять очередь" aria-pressed="false" disabled><svg class="icon"><use href="{{ asset('assets/icons.svg') }}#repeat"></use></svg></button><label class="dock-speed"><span class="visually-hidden">Скорость воспроизведения</span><select id="dockRate" aria-label="Скорость воспроизведения" disabled><option value="0.75">0,75×</option><option value="1" selected>1×</option><option value="1.25">1,25×</option><option value="1.5">1,5×</option></select></label><label class="dock-volume"><svg class="icon"><use href="{{ asset('assets/icons.svg') }}#volume"></use></svg><input id="dockVolume" type="range" min="0" max="1" step="0.05" value="0.8" aria-label="Громкость" disabled></label><a class="dock-icon-button" id="dockDownload" aria-label="Скачать сказку" aria-disabled="true" tabindex="-1"><svg class="icon"><use href="{{ asset('assets/icons.svg') }}#download"></use></svg></a><button class="dock-queue-button" id="dockQueueToggle" type="button" aria-expanded="false" aria-controls="audioQueuePanel" aria-label="Открыть очередь"><svg class="icon"><use href="{{ asset('assets/icons.svg') }}#queue-list"></use></svg><span>Очередь</span><b id="audioQueueCount">0</b></button>
